/**
 * The single source for the public features page and the agent-readable files
 * (`public/llms.txt`, `public/llms-full.txt`, generated by
 * `scripts/build-llms-txt.ts`). Only list what the code really does.
 */

export const REPO_URL = "https://github.com/jasonLaster/oncobase";
export const SITE_URL = "https://diana-tnbc.com";

export type GroupId = "read" | "ask" | "protect" | "data" | "share" | "build";

export type Feature = {
  group: GroupId;
  name: string;
  /** One plain sentence about what it does for the person using it. */
  summary: string;
  /** Where you find it. */
  where: string;
  /** How an agent or script reaches it, when it can. */
  surface?: string;
};

export const groups: { id: GroupId; title: string; tagline: string }[] = [
  { id: "read", title: "Read", tagline: "Find your way around and read comfortably, on any screen." },
  { id: "ask", title: "Ask", tagline: "Search by meaning, or talk to the knowledge base." },
  { id: "protect", title: "Protect", tagline: "Share the science without sharing the patient." },
  { id: "data", title: "See the data", tagline: "Timelines, scans, and slides next to the notes." },
  { id: "share", title: "Share", tagline: "Bring family, doctors, and researchers in." },
  { id: "build", title: "Build", tagline: "Publish from plain files. Extend it with code or agents." },
];

