const groupTitle = (id: GroupId) => groups.find((group) => group.id === id)!.title;

/** The text of `public/llms.txt`: a short index for agents. */
export function renderLlmsTxt(): string {
  return `# Oncobase

> Oncobase is an open-source (MIT) knowledge base for taking control of your care. Publish a vault of markdown notes, papers, and results to a searchable reader with AI search and chat, role-based privacy, inline redaction, and clinical viewers.

It was inspired by Sid Sijbrandij's osteosarc.com (https://osteosarc.com/).

## Start here

- [Everything Oncobase can do](${SITE_URL}/features): the public features page.
- [Full feature and interface list for agents](${SITE_URL}/llms-full.txt): every feature, where it lives, and how to call it.
- [Source code and README](${REPO_URL}): MIT licensed.
- [Diana's knowledge base](${SITE_URL}/): the first site built on Oncobase.

## What it does

${groups.map((group) => `- ${group.title}: ${group.tagline}`).join("\n")}

## Notes for agents

- The reader is a client-rendered web app; most content needs a signed-in session or the site password.
- The public guides at ${SITE_URL}/education and the features page need no password.
- To publish, use the \`oncobase\` CLI (\`oncobase check\`, then \`oncobase publish\`) and the bundled skills (\`oncobase skills\`).
`;
}

/** The text of `public/llms-full.txt`: everything, grouped, plus the interfaces. */
export function renderLlmsFullTxt(): string {
  const sections = groups
    .map((group) => {
      const items = groupFeatures(group.id)
        .map((feature) => `- **${feature.name}** — ${feature.summary} Where: ${feature.where}.${feature.surface ? ` Interface: \`${feature.surface}\`.` : ""}`)
        .join("\n");
      return `## ${group.title}\n\n${group.tagline}\n\n${items}`;
    })
    .join("\n\n");
  const table = [
    "| Name | Kind | What it does | Auth |",
    "| --- | --- | --- | --- |",
    ...interfaces.map((item) => `| \`${item.name}\` | ${item.kind} | ${item.does} | ${item.auth} |`),
  ].join("\n");
  const details = detailItems.map((item) => `- **${item.title}.** ${item.text}`).join("\n");
  return `# Oncobase: every feature

Oncobase is an open-source (MIT) knowledge base for taking control of your care. Source: ${REPO_URL}. Live example: ${SITE_URL}/. Inspired by Sid Sijbrandij's osteosarc.com (https://osteosarc.com/).

Auth key: Gate = the site's shared-password cookie; Session = an account cookie; Publish token = \`Authorization: Bearer wpt_…\`; Public = none.

${sections}

## Interfaces

${table}

## Details

${details}

Not available today: sorting or filtering inside tables, an MCP server, and automatic dark-theme swapping of illustration pairs inside the reader (illustrations are authored as light and dark pairs; pages like the landing and features pages pick the matching one).
`;
}

export { groupTitle };
